<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/admin-auth.php'; $pdo=getPDO(); requireAdminLogin(); if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['id']; $status=$_POST['order_status']; $allowed=['Pending','Confirmed','Preparing','Out for Delivery','Delivered']; if(in_array($status,$allowed,true)){ $s=$pdo->prepare('UPDATE orders SET order_status=? WHERE id=?'); $s->execute([$status,$id]); } header('Location: orders.php'); exit; } $rows=$pdo->query('SELECT o.*,c.name FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC')->fetchAll(); ?><!doctype html><html><head><title>Orders</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'partials/sidebar.php'; ?><main class="section"><div class="container"><h1>Order Management</h1><table class="admin-table"><tr><th>ID</th><th>Customer</th><th>Total</th><th>Delivery</th><th>Payment</th><th>Status</th><th>Save</th></tr><?php foreach($rows as $r): ?><tr><td>#<?php echo $r['id']; ?></td><td><?php echo htmlspecialchars($r['name']); ?></td><td>₹<?php echo number_format($r['total_amount'],2); ?></td><td><?php echo htmlspecialchars($r['delivery_date']); ?></td><td><?php echo htmlspecialchars($r['payment_method']); ?></td><td><form method="post"><input type="hidden" name="id" value="<?php echo $r['id']; ?>"><select name="order_status"><?php foreach(['Pending','Confirmed','Preparing','Out for Delivery','Delivered'] as $s): ?><option <?php echo $r['order_status']===$s?'selected':''; ?>><?php echo $s; ?></option><?php endforeach; ?></select></td><td><button class="btn btn-small">Update</button></form></td></tr><?php endforeach; ?></table></div></main></body></html>
